const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([73.931617, 31.998723]);
  const region = point.buffer(10000); // 10km buffer
  const start2003 = '2003-01-01';
  const end2003 = '2003-12-31';
  const start2013 = '2013-01-01';
  const end2013 = '2013-12-31';

  // 2. Data Acquisition - GRACE MASCON product
  const grace = ee.ImageCollection('GRACE/GRACE-FO/MASCON/CRI/GRID_RL06_V2')
    .select('lwe_thickness'); // equivalent water thickness in cm

  const grace2003 = grace.filterDate(start2003, end2003);
  const grace2013 = grace.filterDate(start2013, end2013);

  // Check collection sizes
  const count2003 = grace2003.size().getInfo();
  const count2013 = grace2013.size().getInfo();

  console.log(`2003 Images: ${count2003}, 2013 Images: ${count2013}`);

  if (count2003 === 0 || count2013 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Compute annual means
  const mean2003 = grace2003.mean();
  const mean2013 = grace2013.mean();

  // 4. Get pixel counts to check for valid data
  const countReducer = ee.Reducer.count();

  const countPixels2003 = mean2003.reduceRegion({
    reducer: countReducer,
    geometry: region,
    scale: 50000, // GRACE resolution ~300km, using 50km scale
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const countPixels2013 = mean2013.reduceRegion({
    reducer: countReducer,
    geometry: region,
    scale: 50000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`Valid pixels 2003: ${countPixels2003}, 2013: ${countPixels2013}`);

  if (countPixels2003 === 0 || countPixels2013 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate mean groundwater values
  const reducer = ee.Reducer.mean();

  const gw2003 = mean2003.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: 50000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const gw2013 = mean2013.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: 50000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`GW 2003: ${gw2003?.toFixed(2)} cm, GW 2013: ${gw2013?.toFixed(2)} cm`);

  // 6. Validation & Final Answer
  if (gw2003 === null || gw2013 === null || 
      isNaN(gw2003) || isNaN(gw2013) ||
      Math.abs(gw2003) > 1000 || Math.abs(gw2013) > 1000) { // Sanity check
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = gw2013 - gw2003;
  console.log(`Difference (2013-2003): ${difference?.toFixed(2)} cm`);

  // Significant decline threshold: >5cm decline (negative difference)
  if (difference < -5) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
